_WORD_CHAR = re.compile(r"[a-zA-Z]")


def is_word_char(c) -> bool:
    # JS coerces a missing character to the string "undefined" before testing it.
    return bool(_WORD_CHAR.search(c if c is not None else "undefined"))
########## rules_builder/parse_space.py
def _at(src: str, pos: int):
    return src[pos] if 0 <= pos < len(src) else None


def parse_space(src: str, pos: int, newline_ok: bool) -> int:
    while _at(src, pos) in (" ", "\t", "#") or (
        newline_ok and _at(src, pos) in ("\r", "\n")
    ):
        if _at(src, pos) == "#":
            while _at(src, pos) and _at(src, pos) not in ("\r", "\n"):
                pos += 1
        else:
            pos += 1
    return pos
