from typing import Callable, Dict, Generic, Iterator, Optional, TypeVar

T = TypeVar("T")
K = TypeVar("K")


class GenericSet(Generic[T, K]):
    """A Set keyed by an arbitrary derived key.

    The backing store is identity based, mirroring the JS `Set` the reference
    implementation uses, so elements that merely compare equal are still distinct.
    """

    def __init__(self, get_key: Callable[[T], K]):
        self._keys: Dict[K, T] = {}
