cd /workspace/ported_implementation && cat > /tmp/smoke.test.ts <<'EOF'
import { test } from 'vitest';
import GBNF, { GrammarParseError, InputParseError } from 'gbnf';
import { writeFileSync } from 'node:fs';

test('smoke', () => {
  const out: any[] = [];
  const g = 'root ::= ("foo" | [a-z]+ )\nbar ::= "b"\n';
  const st: any = GBNF(g);
  out.push(['rules', [...st.rules()].map((r: any) => r.value !== undefined ? { type: r.type, value: r.value } : { type: r.type })]);
  out.push(['size', st.size]);
  out.push(['grammar', st.grammar]);
  out.push(['graph', st.graph.print()]);

  const st2: any = GBNF('root ::= [a-z]+', [102, 111]);
  out.push(['cp', [...st2.rules()].map((r: any) => ({ type: r.type, value: r.value ?? null }))]);

  let st3 = GBNF('root ::= "bar"').add('b').add('a');
  try {
    st3.add('z');
  } catch (e) {
    const err = e as InputParseError;
    out.push(['msg', err.message]);
    out.push(['recent', err.errorForMostRecentInput]);
    out.push(['src', err.src]);
  }

  for (const grammar of ['root ::= foo\nfoo ::= baz\nbar ::= "bar"\n  ', 'a ::= "x"']) {
    try {
      GBNF(grammar);
    } catch (e) {
      out.push(['gerr', (e as GrammarParseError).message]);
    }
  }
  writeFileSync('/tmp/ts_out.json', JSON.stringify(out, null, 1));
});
EOF
cp /tmp/smoke.test.ts tests/smoke.test.ts && timeout 300 vitest run --config vitest.config.unit.ts tests/smoke.test.ts 2>&1 | tail -20 && diff <(python3 -c "import json,sys; print(json.dumps(json.load(open('/tmp/py_out.json')),indent=1))") <(python3 -c "import json,sys; print(json.dumps(json.load(open('/tmp/ts_out.json')),indent=1))") && echo "PARITY: IDENTICAL"
